import csv
occ='0361d2c1-48db-57ae-b48b-913d1c1cef38'
pow='49eac0ff-63d2-57a8-90a0-fdee8aaf25a6'
vals={}
with open(VALUES_CSV) as f:
    for row in csv.DictReader(f):
        if row['timeseries_id'] in (occ,pow):
            tid=row['timeseries_id']
            if tid not in vals: vals[tid]={}
            vals[tid][row['timestamp']]=row['value']
d='2018-01-10'
o=vals.get(occ,{}); p=vals.get(pow,{})
common=[t for t in o if t.startswith(d) and t in p]
count=0
for t in sorted(common):
    try:
        ov=float(o[t]); pv=float(p[t])
    except: continue
    if pv>1.0 and ov==0:
        count+=1
print(len(common),count)
